scripts.script:
local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Window = Rayfield:CreateWindow({
    Name = "Custom Wins & Coins By Sqilss",
    LoadingTitle = "Loading Sqilss",
    LoadingSubtitle = "by Sqilss",
    ConfigurationSaving = {
        Enabled = false,
    },
})

local MainTab = Window:CreateTab("Main", 4483362458)

-- Default values
local WinsAmount = 100000000000    -- 100 Billion
local CoinsAmount = 100000000000   -- 100 Billion

-- Wins Input
MainTab:CreateInput({
    Name = "Wins Amount",
    PlaceholderText = "Enter amount (e.g. 100000000000 or 1e11)",
    RemoveTextAfterFocusLost = false,
    Callback = function(Text)
        local num = tonumber(Text) or tonumber(loadstring("return " .. Text)()) or WinsAmount
        WinsAmount = math.max(1, num)  -- prevent negative or zero
    end,
})

-- Coins Input
MainTab:CreateInput({
    Name = "Coins Amount",
    PlaceholderText = "Enter amount (e.g. 100000000000 or 1e11)",
    RemoveTextAfterFocusLost = false,
    Callback = function(Text)
        local num = tonumber(Text) or tonumber(loadstring("return " .. Text)()) or CoinsAmount
        CoinsAmount = math.max(1, num)
    end,
})

-- Give Wins Button
MainTab:CreateButton({
    Name = "Give Wins",
    Callback = function()
        local args = {
            [1] = WinsAmount,
            [2] = "Wins"
        }
        game:GetService("ReplicatedStorage")
            :WaitForChild("Remote")
            :WaitForChild("Event")
            :WaitForChild("Race")
            :WaitForChild("AddCoinsOrWins")
            :FireServer(unpack(args))

        Rayfield:Notify({
            Title = "✅ Success",
            Content = "Gave " .. WinsAmount .. " Wins",
            Duration = 3,
        })
    end,
})

-- Give Coins Button
MainTab:CreateButton({
    Name = "Give Coins",
    Callback = function()
        local args = {
            [1] = CoinsAmount,
            [2] = "Coins"
        }
        game:GetService("ReplicatedStorage")
            :WaitForChild("Remote")
            :WaitForChild("Event")
            :WaitForChild("Race")
            :WaitForChild("AddCoinsOrWins")
            :FireServer(unpack(args))

        Rayfield:Notify({
            Title = "✅ Success",
            Content = "Gave " .. CoinsAmount .. " Coins",
            Duration = 3,
        })
    end,
})

-- Give Both Button
MainTab:CreateButton({
    Name = "Give Both Wins + Coins",
    Callback = function()
        -- Wins
        game:GetService("ReplicatedStorage").Remote.Event.Race.AddCoinsOrWins:FireServer(WinsAmount, "Wins")
        -- Coins
        game:GetService("ReplicatedStorage").Remote.Event.Race.AddCoinsOrWins:FireServer(CoinsAmount, "Coins")

        Rayfield:Notify({
            Title = "✅ Success",
            Content = "Gave " .. WinsAmount .. " Wins & " .. CoinsAmount .. " Coins",
            Duration = 4,
        })
    end,
})

-- Optional: Quick preset buttons
MainTab:CreateButton({
    Name = "Set 100 Billion (100B)",
    Callback = function()
        WinsAmount = 100000000000
        CoinsAmount = 100000000000
        Rayfield:Notify({Title = "Preset", Content = "Set to 100 Billion each", Duration = 2})
    end,
})

MainTab:CreateButton({
    Name = "Set 1 Trillion (1T)",
    Callback = function()
        WinsAmount = 1000000000000
        CoinsAmount = 1000000000000
        Rayfield:Notify({Title = "Preset", Content = "Set to 1 Trillion each", Duration = 2})
    end,
})

Rayfield:Notify({
    Title = "UI Loaded",
    Content = "Type any amount in the boxes and press the buttons",
    Duration = 5,
})
